// Generated by npm run build:preview.
(async () => {
"use strict";
const previewRequest = (() => {
  const storageKey = 'ram-for-bic-commonroom-preview-v2';
  const previousKey = 'ram-for-bic-static-commonroom-v1';
  const user = { id: 'preview-guest', name: 'You', isGuest: true };
  const rooms = {
    global: { name: 'global', topic: 'Talk across classes.', server: 'campus' },
    announcements: { name: 'announcements', topic: 'Sample student program and activity updates.', server: 'campus', readOnly: true },
    'class-a': { name: 'class-a', topic: 'Coordinate with Class A.', server: 'classes' },
    'class-b': { name: 'class-b', topic: 'Coordinate with Class B.', server: 'classes' },
  };
  const spaces = { campus: 'campus', classes: 'classes', global: 'global', classA: 'class-a', classB: 'class-b' };
  const names = { campus: 'BIC Campus', classes: 'Class rooms' };
  const date = Date.parse('2026-11-26T10:00:00+01:00');
  const example = (id, author, text, extra) => ({ id, author, text, createdAt: date, ...extra });
  const visitorPost = (id, text) => ({ id, author: user.name, authorId: user.id, text, createdAt: Date.now() });
  const sample = {
    global: [
      example('sample-meet', 'Maya', 'Does anyone want to meet at the entrance before the welcome session?'),
      example('sample-join', 'Leon', 'I can join. We could compare what we need for the first week.'),
    ],
    announcements: [
      example('sample-announcement', 'Campus team', 'Sample update. A peer study group will meet in the student lounge this week.'),
    ],
    'class-a': [example('sample-class-a', 'Maya', 'I’m putting together a study group. Which afternoons work for you?')],
    'class-b': [example('sample-class-b', 'Leon', 'I made a list of topics to review. Does anyone want to go through it after class?')],
  };
  const sampleBoards = {
    threads: [example('sample-issue', 'Maya', 'Could BIC post timetable changes in one place?', {
      title: 'Make timetable changes easier to find', scope: 'campus',
      replies: [example('sample-issue-reply', 'Leon', 'A notice with the new room and time would help.')],
    })],
    help: [example('sample-help', 'Sam', 'I’m getting ready for my first week. Where should I look for arrival details?', {
      title: 'What should I check before my first day?', scope: 'campus',
      replies: [example('sample-help-reply', 'Maya', 'Start with your welcome information in Classter.')],
    })],
  };
  const members = [user, { id: 'preview-maya', name: 'Maya' }, { id: 'preview-leon', name: 'Leon' }];
  let memory;
  let canPersist = true;

  function saved(key) {
    try { return JSON.parse(localStorage.getItem(key)); } catch { return null; }
  }

  function initialize() {
    const previous = saved(previousKey);
    const messages = Object.fromEntries(Object.entries(sample).map(([channel, rows]) => {
      const legacy = Array.isArray(previous?.[channel === 'global' ? 'campus' : channel])
        ? previous[channel === 'global' ? 'campus' : channel] : [];
      const personal = legacy.filter((row) => row.author === 'You').map((row, index) =>
        visitorPost('previous-' + channel + '-' + index, row.text));
      return [channel, [...rows, ...personal].map((row, index) => ({
        ...row, seq: index + 1, revision: 0, reactions: [],
        ...(row.id.startsWith('sample-') ? { authorId: 'example-' + row.author.toLowerCase() } : {}),
      }))];
    }));
    const boards = structuredClone(sampleBoards);
    for (const kind of ['threads', 'help']) {
      const old = previous?.[kind === 'threads' ? 'issues' : kind];
      if (!Array.isArray(old)) continue;
      for (const row of old) {
        const entry = boards[kind].find((topic) => topic.id === row.id);
        const replies = Array.isArray(row.replies) ? row.replies
          .filter((reply) => reply.author === 'You')
          .map((reply, index) => visitorPost('previous-' + row.id + '-' + index, reply.text)) : [];
        const stance = row.stance === 'Agree' ? 'agree' : row.stance === 'Disagree' ? 'disagree' : null;
        if (entry) {
          entry.replies.push(...replies);
          entry.stance = stance;
        } else if (row.author === 'You' && typeof row.id === 'string') {
          boards[kind].push({ ...visitorPost(row.id, row.text), title: row.title, scope: 'campus', replies, stance });
        }
      }
    }
    return { messages, boards, reads: {}, revision: 0 };
  }

  function database() {
    return (canPersist ? saved(storageKey) : null) ?? (memory ??= initialize());
  }

  function save(db) {
    memory = db;
    try {
      localStorage.setItem(storageKey, JSON.stringify(db));
    } catch {
      canPersist = false;
      document.dispatchEvent(new Event('commonroom-preview-temporary'));
    }
  }

  function fail(message, status = 400) {
    throw Object.assign(new Error(message), { status });
  }

  function content(value, label, max, min = 1) {
    const text = typeof value === 'string' ? value.trim() : '';
    if (text.length < min || text.length > max) fail(label + ' must have ' + min + '–' + max + ' characters.');
    return text;
  }

  function revise(db, row) {
    row.revision = ++db.revision;
    save(db);
  }

  function feed(db, rows, params) {
    if (params.has('cursor')) {
      const cursor = Number(params.get('cursor'));
      return { messages: rows.filter((row) => row.revision > cursor), cursor: db.revision, more: false };
    }
    const before = Number(params.get('before') ?? Infinity);
    const history = rows.filter((row) => row.seq < before);
    return { messages: history.slice(-40), cursor: db.revision, hasOlder: history.length > 40 };
  }

  function server(db, id) {
    const channels = Object.entries(rooms).filter(([, room]) => room.server === id).map(([channel, room]) => ({
      id: channel, ...room,
      unread: db.messages[channel].filter((row) => row.seq > (db.reads[channel] ?? 0) && row.authorId !== user.id).length,
    }));
    return { id, name: names[id], role: 'member', channels, members };
  }

  function readMessage(db, id) {
    const row = Object.values(db.messages).flat().find((message) => message.id === id && !message.deletedAt);
    if (!row) fail('This message is unavailable.', 404);
    return row;
  }

  function threadSummary({ replies, ...thread }) {
    return { ...thread, replyCount: replies.length,
      agreeCount: Number(thread.stance === 'agree'), disagreeCount: Number(thread.stance === 'disagree') };
  }

  function boardAction(db, area, id, resource, method, input) {
    const board = db.boards[area];
    if (!id && method === 'GET') return { threads: board.map(threadSummary).reverse() };
    if (!id && method === 'POST') {
      let thread = board.find((item) => item.id === input.id);
      if (!thread) {
        if (!['campus', 'class-a', 'class-b'].includes(input.scope)) fail('Choose a discussion space.');
        thread = { ...visitorPost(input.id, content(input.text, 'Details', 2400, 3)),
          title: content(input.title, 'Title', 100, 3), scope: input.scope, replies: [], stance: null };
        board.push(thread);
        save(db);
      }
      return { thread: threadSummary(thread) };
    }
    const thread = board.find((item) => item.id === id);
    if (!thread) fail('This discussion is unavailable.', 404);
    if (!resource && method === 'GET') return { thread: threadSummary(thread), replies: thread.replies };
    if (resource === 'replies' && method === 'POST') {
      let reply = thread.replies.find((item) => item.id === input.id);
      if (!reply) {
        reply = visitorPost(input.id, content(input.text, 'Response', 1600));
        thread.replies.push(reply);
        save(db);
      }
      return { reply };
    }
    if (area === 'threads' && resource === 'stance' && method === 'PUT') {
      if (![null, 'agree', 'disagree'].includes(input.stance)) fail('Choose a position.');
      thread.stance = input.stance;
      save(db);
      return { thread: threadSummary(thread) };
    }
    fail('This discussion action is unavailable.', 404);
  }

  return async (path, method = 'GET', input = {}) => {
    const url = new URL(path, 'https://preview.invalid');
    const [area, id, resource] = url.pathname.slice(1).split('/');
    const db = database();
    if (area === 'auth' && id === 'guest') return { user, spaces };
    if (area === 'threads' || area === 'help') return boardAction(db, area, id, resource, method, input);
    if (area === 'servers' && Object.hasOwn(names, id)) {
      if (resource !== 'search') return server(db, id);
      const q = content(url.searchParams.get('q'), 'Search', 80).toLowerCase();
      const matches = server(db, id).channels.flatMap((channel) => db.messages[channel.id]
        .filter((message) => !message.deletedAt && message.text.toLowerCase().includes(q))
        .map((message) => ({ ...message, channelId: channel.id, channel: channel.name })));
      return { matches: matches.slice(0, 50) };
    }
    if (area === 'channels' && Object.hasOwn(rooms, id)) {
      const rows = db.messages[id];
      if (resource === 'read' && method === 'POST') {
        if (input.seq > (db.reads[id] ?? 0)) { db.reads[id] = input.seq; save(db); }
        return { ok: true };
      }
      if (resource === 'messages' && method === 'GET') return feed(db, rows, url.searchParams);
      if (resource === 'messages' && method === 'POST' && !rooms[id].readOnly) {
        const previous = rows.find((row) => row.id === input.id);
        if (previous) return { message: previous };
        const message = { ...visitorPost(input.id, content(input.text, 'Message', 2000)),
          seq: (rows.at(-1)?.seq ?? 0) + 1, reactions: [] };
        if (input.replyToId) {
          const quoted = rows.find((row) => row.id === input.replyToId && !row.deletedAt);
          if (!quoted) fail('Choose a reply from this channel.');
          Object.assign(message, { replyToId: quoted.id, replyText: quoted.text.slice(0, 140), replyAuthor: quoted.author });
        }
        rows.push(message);
        revise(db, message);
        return { message };
      }
    }
    if (area === 'messages') {
      const message = readMessage(db, id);
      if (resource === 'reaction' && method === 'PUT') {
        message.reactions = message.reactions.filter((entry) => entry.emoji !== input.emoji);
        if (input.active) message.reactions.push({ emoji: input.emoji, count: 1, mine: true });
      } else if (message.authorId !== user.id) {
        fail('You can only change your own messages.', 403);
      } else if (method === 'PATCH') {
        if ((message.editedAt ?? null) !== input.editedAt) fail('This message changed. Reopen it to edit.', 409);
        message.text = content(input.text, 'Message', 2000);
        message.editedAt = Date.now();
      } else if (method === 'DELETE') {
        Object.assign(message, { text: '', deletedAt: Date.now(), reactions: [] });
      } else {
        fail('This message action is unavailable.', 404);
      }
      revise(db, message);
      return { message };
    }
    fail('This action is unavailable in the preview.', 404);
  };
})();


const request = previewRequest;

function loadSaved(userId) {
  const fallback = { drafts: {}, edits: {}, queued: [], channel: null };
  try {
    const saved = JSON.parse(localStorage.getItem('commonroom:' + userId));
    return saved && Array.isArray(saved.queued) && saved.drafts ? { ...fallback, ...saved } : fallback;
  } catch {
    return fallback;
  }
}

function saveLocal(userId, data) {
  try {
    localStorage.setItem('commonroom:' + userId, JSON.stringify(data));
    return true;
  } catch {
    return false;
  }
}


const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const reactionEmoji = ['👍', '❤️', '🎉', '👀', '💡'];
const time = new Intl.DateTimeFormat(undefined, { hour: 'numeric', minute: '2-digit' });
const day = new Intl.DateTimeFormat(undefined, { month: 'short', day: 'numeric', year: 'numeric' });

function el(tag, className, content) {
  const item = document.createElement(tag);
  if (className) item.className = className;
  if (content !== undefined) item.textContent = content;
  return item;
}

function action(label, name, id, className = 'secondary') {
  const item = el('button', className, label);
  item.type = 'button';
  item.dataset.action = name;
  if (id) item.dataset.id = id;
  return item;
}

function initials(name) {
  return name.trim().split(/\s+/).slice(0, 2).map((word) => Array.from(word)[0]).join('').toUpperCase();
}

function avatar(name) {
  const tone = ['avatar-gold', 'avatar-indigo', 'avatar-green'][name.charCodeAt(0) % 3] || 'avatar-indigo';
  const node = el('span', 'avatar ' + tone, initials(name));
  node.setAttribute('aria-hidden', 'true');
  return node;
}

function readableTime(millis) {
  const date = new Date(millis);
  return day.format(date) + ', ' + time.format(date);
}

function card(message, user, role, queued = null) {
  const item = el('li', 'message');
  item.dataset.message = message.id;
  item.tabIndex = -1;
  const body = el('div');
  const meta = el('div', 'message-meta');
  const clock = el('time', '', time.format(new Date(message.createdAt)));
  clock.dateTime = new Date(message.createdAt).toISOString();
  clock.title = readableTime(message.createdAt);
  meta.append(el('strong', '', message.author), clock);
  if (message.editedAt) meta.append(el('span', '', 'Edited'));
  body.append(meta);
  if (message.deletedAt) {
    body.append(el('p', 'removed', 'Message removed'));
  } else {
    if (message.replyToId) body.append(el('blockquote', 'reply-quote', message.replyAuthor
      ? message.replyAuthor + ' · ' + (message.replyText || 'Message removed')
      : 'Reply to a message'));
    body.append(el('p', 'message-text', message.text));
    const tools = el('div', 'message-actions');
    if (queued) {
      tools.append(el('span', 'pending', queued.sending ? 'Sending…' : queued.error || 'Waiting to send'));
      if (!queued.sending) tools.append(action('Retry', 'retry-message', message.id), action('Discard', 'discard-message', message.id));
    } else {
      const mine = message.authorId === user.id;
      tools.append(action('Reply', 'reply', message.id), action('React', 'react', message.id));
      if (mine) tools.append(action('Edit', 'edit-message', message.id));
      if (mine || role !== 'member') tools.append(action(mine ? 'Delete' : 'Remove', 'delete-message', message.id));
      const reactions = el('div', 'reaction-row');
      for (const reaction of message.reactions || []) {
        const choice = action(reaction.emoji + ' ' + reaction.count, 'toggle-reaction', message.id);
        choice.dataset.emoji = reaction.emoji;
        choice.setAttribute('aria-pressed', String(Boolean(reaction.mine)));
        choice.setAttribute('aria-label', reaction.emoji + ', ' + reaction.count + ' reactions');
        reactions.append(choice);
      }
      if (reactions.childElementCount) body.append(reactions);
    }
    body.append(tools);
  }
  item.append(avatar(message.author), body);
  return item;
}

function field(label, name, options = {}) {
  const container = el('label', '', label);
  const control = el(options.choices ? 'select' : options.multiline ? 'textarea' : 'input');
  control.name = name;
  control.required = options.required !== false;
  if (options.choices) {
    for (const [value, caption] of options.choices) control.add(new Option(caption, value));
  } else {
    if (options.max) control.maxLength = options.max;
    if (options.multiline) control.rows = 4;
  }
  control.value = options.value ?? control.value;
  container.append(control);
  return container;
}



const scopes = [
  ['campus', 'Campus'],
  ['class-a', 'Class A'],
  ['class-b', 'Class B'],
];
const scopeNames = Object.fromEntries(scopes);

function button(label, className, activate) {
  const node = el('button', className, label);
  node.type = 'button';
  node.addEventListener('click', activate);
  return node;
}

function loadDrafts(storageKey) {
  try {
    const data = JSON.parse(localStorage.getItem(storageKey));
    return { thread: data?.thread ?? {}, replies: data?.replies ?? {} };
  } catch {
    return { thread: {}, replies: {} };
  }
}

function labelScope(scope) {
  return scopeNames[scope] ?? 'Campus';
}

function showTime(createdAt) {
  const date = new Date(createdAt);
  if (!Number.isFinite(date.getTime())) return el('span');
  const node = el('time', '', readableTime(createdAt));
  node.dateTime = date.toISOString();
  return node;
}

function count(number, singular, plural = singular + 's') {
  return number + ' ' + (number === 1 ? singular : plural);
}

function header(title, summary) {
  const section = el('header', 'thread-bar');
  const words = el('div', 'thread-bar__heading');
  const heading = el('h1', 'thread-title', title);
  heading.tabIndex = -1;
  words.append(heading);
  if (summary) words.append(el('p', 'thread-subtitle', summary));
  section.append(words);
  return { section, heading };
}

function formMessage() {
  const message = el('p', 'thread-form-status');
  message.setAttribute('role', 'status');
  message.hidden = true;
  return message;
}

function say(message, value, error = false) {
  message.textContent = value;
  message.dataset.error = String(error);
  message.hidden = !value;
}

function issuePreview(issue, activate, showStances) {
  const item = el('li');
  const preview = button('', 'thread-card', () => activate(issue.id));
  preview.dataset.threadKey = issue.id;
  const main = el('span', 'thread-card__heading');
  main.append(el('strong', '', issue.title), el('span', 'thread-scope', labelScope(issue.scope)));
  const meta = el('span', 'thread-card__meta');
  meta.append(el('span', '', issue.author), showTime(issue.createdAt));
  const stats = el('span', 'thread-card__stats');
  stats.append(el('span', '', count(issue.replyCount, 'response')));
  if (showStances) stats.append(
    el('span', '', count(issue.agreeCount, 'agree', 'agree')),
    el('span', '', count(issue.disagreeCount, 'disagree', 'disagree')),
  );
  preview.append(main, el('span', 'thread-card__excerpt', issue.text), meta, stats);
  item.append(preview);
  return item;
}

function createThreads({ root, guestId, kind = 'issue', notice = () => {}, onAuthExpired = () => {} }) {
  root.classList.add('thread-view');
  root.hidden = true;
  const help = kind === 'help';
  const endpoint = help ? '/help' : '/threads';
  const storageKey = (help ? 'commonroom:help-drafts:v1' : 'commonroom:thread-drafts:v1') + (guestId ? ':' + guestId : '');
  const drafts = loadDrafts(storageKey);
  let storageWarned = false;
  let active = false;
  let screen = '';
  let scope = 'all';
  let selected = null;
  let list = null;
  let detail = null;
  let ui = {};
  let revision = 0;
  let pendingRead = null;
  let writeId = 0;
  let mutations = 0;
  let focusThread = null;

  function saveDrafts() {
    try {
      localStorage.setItem(storageKey, JSON.stringify(drafts));
    } catch {
      if (!storageWarned) notice('Drafts will stay in this tab. Browser storage is unavailable.');
      storageWarned = true;
    }
  }

  function setScreen(name, content, focus) {
    revision++;
    screen = name;
    root.replaceChildren(...content);
    if (focus) root.querySelector('h1')?.focus({ preventScroll: true });
  }

  function networkStatus() {
    const bar = el('div', 'thread-network');
    const message = el('p');
    message.setAttribute('role', 'status');
    bar.append(message, button('Retry', 'thread-link', refresh));
    bar.hidden = true;
    return { bar, message };
  }

  function networkError(error) {
    if (error.status === 401) Promise.resolve().then(onAuthExpired).catch(() => {});
    if (!ui.network) return;
    ui.network.bar.hidden = false;
    ui.network.message.textContent = error.message;
    if (screen === 'list' && list === null) ui.state.textContent = help ? 'Questions could not load.' : 'Threads could not load.';
    if (screen === 'detail' && detail === null) ui.body.textContent = 'This discussion could not load.';
  }

  function listView(focus = true) {
    selected = null;
    detail = null;
    const top = help
      ? header('Help', 'Ask a question or share practical advice with other students.')
      : header('Issue threads', 'Raise issues and hear other students’ perspectives.');
    top.section.append(button(help ? 'Ask a question' : 'New thread', 'thread-primary', composeView));
    const filters = el('div', 'thread-filters');
    filters.setAttribute('role', 'group');
    filters.setAttribute('aria-label', 'Filter threads by scope');
    for (const [value, caption] of [['all', 'All'], ...scopes]) {
      const filter = button(caption, 'thread-filter', () => {
        scope = value;
        renderList(true);
      });
      filter.dataset.scope = value;
      filters.append(filter);
    }
    const network = networkStatus();
    const scroll = el('div', 'thread-scroll');
    const state = el('p', 'thread-empty');
    const results = el('ol', 'thread-list');
    results.setAttribute('aria-label', help ? 'Help questions' : 'Issue threads');
    scroll.append(state, results);
    ui = { filters, network, scroll, state, results, signature: '' };
    setScreen('list', [top.section, filters, network.bar, scroll], focus);
    renderList();
    refresh();
  }

  function renderList(resetScroll = false) {
    for (const filter of ui.filters.children) {
      filter.setAttribute('aria-pressed', String(filter.dataset.scope === scope));
    }
    const visible = (list ?? []).filter((issue) => scope === 'all' || issue.scope === scope);
    const signature = JSON.stringify(visible);
    if (signature !== ui.signature) {
      const key = ui.results.contains(document.activeElement) ? document.activeElement.dataset.threadKey : focusThread;
      ui.results.replaceChildren(...visible.map((issue) => issuePreview(issue, detailView, !help)));
      if (key) Array.from(ui.results.querySelectorAll('[data-thread-key]'))
        .find((card) => card.dataset.threadKey === key)?.focus({ preventScroll: true });
      focusThread = null;
      ui.signature = signature;
    }
    ui.state.hidden = visible.length !== 0;
    ui.state.textContent = help
      ? (list === null ? 'Loading questions…' : scope === 'all' ? 'No questions yet. Ask the first one.' : 'No questions in this scope yet.')
      : list === null
      ? 'Loading threads…'
      : scope === 'all' ? 'No issues have been posted yet. Start with a new thread.' : 'No issues in this scope yet.';
    if (resetScroll) ui.scroll.scrollTop = 0;
  }

  function composeView() {
    const top = help
      ? header('Ask a question', 'Describe what you need so another student can help.')
      : header('Start a thread', 'Keep the title short and describe what would help.');
    top.section.prepend(button('Back', 'thread-link', () => listView()));
    const scroll = el('div', 'thread-scroll');
    const form = el('form', 'thread-form');
    const draft = drafts.thread;
    const scopeField = field('Scope', 'scope', { choices: scopes, value: draft.scope ?? (scope === 'all' ? 'campus' : scope) });
    const title = field('Title', 'title', { max: 100, value: draft.title ?? '' });
    const text = field(help ? 'Question details' : 'Issue details', 'text', { max: 2400, multiline: true, value: draft.text ?? '' });
    const submit = el('button', 'thread-primary', help ? 'Post question' : 'Post thread');
    submit.type = 'submit';
    const message = formMessage();
    form.append(
      scopeField, title, text,
      el('p', 'thread-form-hint', 'Choose a scope and keep personal details out of shared threads.'),
      message, submit,
    );
    scroll.append(form);
    setScreen('compose', [top.section, scroll], false);
    form.elements.title.minLength = 3;
    form.elements.text.minLength = 3;
    form.elements.title.focus({ preventScroll: true });
    form.addEventListener('input', () => {
      Object.assign(draft, Object.fromEntries(new FormData(form)));
      saveDrafts();
    });
    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      const payload = {
        title: form.elements.title.value.trim(),
        text: form.elements.text.value.trim(),
        scope: form.elements.scope.value,
      };
      if (payload.title.length < 3 || payload.text.length < 3) {
        say(message, 'Add at least three characters to the title and details.', true);
        return;
      }
      if (submit.disabled || mutations > 0) return;
      const route = revision;
      const id = draft.pending ?? crypto.randomUUID();
      draft.pending = id;
      Object.assign(draft, payload);
      saveDrafts();
      submit.disabled = true;
      say(message, 'Posting…');
      mutations++;
      writeId++;
      try {
        const { thread } = await request(endpoint, 'POST', { id, ...payload });
        if (thread.title !== payload.title || thread.text !== payload.text || thread.scope !== payload.scope) {
          delete draft.pending;
          saveDrafts();
          say(message, 'An earlier version was already posted. Your changes are still in this draft.', true);
          return;
        }
        if (draft.title === payload.title && draft.text === payload.text && draft.scope === payload.scope) {
          drafts.thread = {};
        } else {
          delete draft.pending;
        }
        saveDrafts();
        if (active && route === revision) detailView(thread.id, thread);
        else notice(help ? 'Question posted.' : 'Thread posted.');
      } catch (error) {
        if (error.status === 401) Promise.resolve().then(onAuthExpired).catch(() => {});
        if (error.status === 409) {
          delete draft.pending;
          saveDrafts();
          say(message, 'An earlier version may already be posted in a different scope. Your draft is saved here.', true);
        } else {
          say(message, error.message + ' Your draft is saved here.', true);
        }
        submit.textContent = 'Retry post';
      } finally {
        mutations--;
        writeId++;
        submit.disabled = false;
        refresh();
      }
    });
  }

  function detailView(threadId, posted) {
    selected = threadId;
    const cached = posted ?? list?.find((thread) => thread.id === threadId);
    detail = null;
    const top = header(cached?.title ?? 'Thread');
    top.section.prepend(button('Back', 'thread-link', () => {
      focusThread = threadId;
      listView();
    }));
    const network = networkStatus();
    const scroll = el('div', 'thread-scroll');
    const original = el('article', 'thread-original');
    const scopeTag = el('span', 'thread-scope');
    const originalMeta = el('div', 'thread-author');
    const body = el('p', 'thread-body', help ? 'Loading question…' : 'Loading issue…');
    const stance = el('div', 'thread-stances');
    stance.setAttribute('role', 'group');
    stance.setAttribute('aria-label', 'Your position on this issue');
    const agree = button('Agree', 'thread-stance', () => setStance('agree'));
    const disagree = button('Disagree', 'thread-stance', () => setStance('disagree'));
    stance.append(agree, disagree);
    stance.hidden = true;
    original.append(scopeTag, originalMeta, body, stance);
    const responses = el('section', 'thread-responses');
    const responseTitle = el('h2', '', 'Responses');
    responseTitle.id = help ? 'help-responses-heading' : 'thread-responses-heading';
    responses.setAttribute('aria-labelledby', responseTitle.id);
    const empty = el('p', 'thread-empty', 'No responses yet. Add your perspective.');
    const replies = el('ol', 'thread-replies');
    responses.append(responseTitle, empty, replies);
    responses.hidden = true;
    scroll.append(original, responses);
    const form = el('form', 'thread-reply-form');
    const draft = drafts.replies[threadId] ?? {};
    const responseField = field('Add a response', 'text', { max: 1600, multiline: true, value: draft.text ?? '' });
    const submit = el('button', 'thread-primary', 'Send response');
    submit.type = 'submit';
    const message = formMessage();
    form.append(responseField, submit, message);
    form.hidden = true;
    form.elements.text.rows = 2;
    ui = { top, network, scroll, scopeTag, originalMeta, body, stance, agree, disagree, responses, empty, replies, form, signature: '' };
    setScreen('detail', [top.section, network.bar, scroll, form], true);
    if (posted) {
      detail = { thread: posted, replies: [] };
      renderDetail();
    }
    const route = revision;
    form.addEventListener('input', () => {
      draft.text = form.elements.text.value;
      drafts.replies[threadId] = draft;
      saveDrafts();
    });
    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      const text = form.elements.text.value.trim();
      if (!text || submit.disabled || mutations > 0 || route !== revision) return;
      draft.text = text;
      draft.pending ??= crypto.randomUUID();
      drafts.replies[threadId] = draft;
      saveDrafts();
      submit.disabled = true;
      say(message, 'Sending…');
      mutations++;
      writeId++;
      try {
        const { reply } = await request(endpoint + '/' + threadId + '/replies', 'POST', { id: draft.pending, text });
        if (reply.text !== text) {
          delete draft.pending;
          saveDrafts();
          say(message, 'An earlier response was already sent. Your changes are still in this draft.', true);
          return;
        }
        if (form.elements.text.value.trim() === text) {
          delete drafts.replies[threadId];
          form.elements.text.value = '';
          draft.text = '';
        }
        delete draft.pending;
        saveDrafts();
        say(message, 'Response sent.');
        submit.textContent = 'Send response';
        if (active && route === revision && detail && !detail.replies.some((item) => item.id === reply.id)) {
          detail.replies = [...detail.replies, reply];
          detail.thread = { ...detail.thread, replyCount: detail.thread.replyCount + 1 };
          renderDetail();
          ui.scroll.scrollTop = ui.scroll.scrollHeight;
        }
      } catch (error) {
        if (error.status === 401) Promise.resolve().then(onAuthExpired).catch(() => {});
        say(message, error.message + ' Your response is saved here.', true);
        submit.textContent = 'Retry response';
      } finally {
        mutations--;
        writeId++;
        submit.disabled = false;
        refresh();
      }
    });
    refresh();
  }

  function renderDetail() {
    const { thread, replies } = detail;
    ui.top.heading.textContent = thread.title;
    ui.scopeTag.textContent = labelScope(thread.scope);
    ui.originalMeta.replaceChildren(avatar(thread.author), el('strong', '', thread.author), showTime(thread.createdAt));
    ui.body.textContent = thread.text;
    for (const [choice, value, total] of [
      [ui.agree, 'agree', thread.agreeCount],
      [ui.disagree, 'disagree', thread.disagreeCount],
    ]) {
      choice.textContent = (value === 'agree' ? 'Agree' : 'Disagree') + ' · ' + total;
      choice.setAttribute('aria-pressed', String(thread.stance === value));
    }
    ui.stance.hidden = help;
    ui.responses.hidden = ui.form.hidden = false;
    ui.empty.hidden = replies.length > 0;
    const signature = JSON.stringify(replies);
    if (signature !== ui.signature) {
      ui.replies.replaceChildren(...replies.map((reply) => {
        const item = el('li', 'thread-response');
        const meta = el('div', 'thread-author');
        meta.append(avatar(reply.author), el('strong', '', reply.author), showTime(reply.createdAt));
        item.append(meta, el('p', 'thread-body', reply.text));
        return item;
      }));
      ui.signature = signature;
    }
  }

  async function setStance(value) {
    if (!detail || ui.agree.disabled || mutations > 0) return;
    const route = revision;
    const threadId = selected;
    const stance = detail.thread.stance === value ? null : value;
    ui.agree.disabled = ui.disagree.disabled = true;
    mutations++;
    writeId++;
    try {
      const { thread } = await request('/threads/' + threadId + '/stance', 'PUT', { stance });
      if (active && route === revision) {
        detail.thread = thread;
        renderDetail();
      }
    } catch (error) {
      if (active && route === revision) networkError(error);
    } finally {
      mutations--;
      writeId++;
      if (active && route === revision) ui.agree.disabled = ui.disagree.disabled = false;
      refresh();
    }
  }

  async function refresh() {
    if (!active || root.hidden || screen === 'compose' || mutations > 0) return;
    const route = revision;
    const written = writeId;
    if (pendingRead?.route === route && pendingRead.written === written) return;
    const ticket = { route, written };
    pendingRead = ticket;
    try {
      const response = await request(screen === 'detail' ? endpoint + '/' + selected : endpoint);
      if (!active || route !== revision || pendingRead !== ticket || written !== writeId) return;
      ui.network.bar.hidden = true;
      if (screen === 'detail') {
        detail = response;
        renderDetail();
      } else {
        list = response.threads;
        renderList();
      }
    } catch (error) {
      if (active && route === revision && pendingRead === ticket && written === writeId) networkError(error);
    } finally {
      if (pendingRead === ticket) pendingRead = null;
    }
  }

  return {
    open() {
      root.hidden = false;
      if (active) return;
      active = true;
      listView();
    },
    close() {
      active = false;
      revision++;
      root.hidden = true;
    },
    poll: refresh,
  };
}



const view = $('#workspace');
const dialog = $('#dialog');
const stream = $('#stream');
const composer = $('#composer');
const input = $('#message-input');
const state = {
  user: null, spaces: null, servers: [], server: null, channel: null,
  rows: new Map(), cursor: null, before: null, older: false, navigation: 0,
  saved: null, replying: null, sending: new Set(),
  pane: 'chat', syncing: false, reachedBottom: true, lastRead: 0, loading: false,
};
let starting = false;
let toastTimer;
let dialogVersion = 0;
const boards = new Map();

const localPreview = document.documentElement.hasAttribute('data-local-preview');
let temporaryPreview = false;
const deviceTheme = matchMedia('(prefers-color-scheme: dark)');
const embedded = new URLSearchParams(location.search).has('embedded');
function updateTheme() {
  let theme = localPreview || deviceTheme.matches ? 'dark' : 'light';
  if (localPreview) {
    try { theme = localStorage.getItem('ram-for-bic-theme') || theme; }
    catch { /* The preview can still open without browser storage. */ }
  }
  if (embedded) {
    try { theme = window.parent.document.documentElement.dataset.theme || theme; }
    catch { /* Device theme remains available outside the campaign origin. */ }
  }
  document.documentElement.dataset.theme = theme;
  $('meta[name="theme-color"]').content = getComputedStyle(document.documentElement).getPropertyValue('--background').trim();
}
if (embedded) {
  try {
    new MutationObserver(updateTheme).observe(window.parent.document.documentElement, { attributeFilter: ['data-theme'] });
  } catch { /* The standalone theme has no parent dependency. */ }
}
deviceTheme.addEventListener('change', updateTheme);
updateTheme();

function notice(message) {
  const toast = $('#toast');
  toast.textContent = message;
  toast.hidden = false;
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => { toast.hidden = true; }, 6500);
}

function status(element, message, error = false) {
  element.textContent = message;
  element.dataset.error = String(error);
}

function connected(online, label) {
  const bar = $('#connection');
  bar.dataset.state = online ? 'online' : 'offline';
  const heading = $('#connection-label');
  const connectionLabel = localPreview && online ? (temporaryPreview ? 'Temporary demo' : 'Local demo') : label;
  if (heading.textContent !== connectionLabel) heading.textContent = connectionLabel;
  $('[data-action="retry-connection"]', bar).hidden = online;
}

function remember() {
  if (!state.user || !saveLocal(state.user.id, state.saved)) notice('Browser storage is unavailable. Keep this tab open to retain your draft.');
}

function pane(name) {
  state.pane = name;
  view.dataset.pane = name;
  const active = boards.has(name) || name === 'people' ? name
    : name === 'rooms' || state.server?.id === state.spaces?.classes ? 'classes' : 'global';
  for (const button of $$('nav button[data-action]')) {
    if (!['global', 'classes', 'issues', 'help', 'people'].includes(button.dataset.action)) continue;
    button.toggleAttribute('aria-current', button.dataset.action === active);
    if (button.dataset.action === active) button.setAttribute('aria-current', 'true');
  }
  if (name === 'chat') updateRead().catch(connectionError);
}

function connectionError(error) {
  if (error.status === 401) return reconnectGuest();
  connected(false, 'Offline');
}

function channelLabel(channel) {
  if (channel.id === state.spaces.global) return 'Global chat';
  if (channel.id === state.spaces.classA) return 'Class A';
  if (channel.id === state.spaces.classB) return 'Class B';
  return channel.name === 'announcements' ? 'Announcements' : channel.name;
}

function replaceControls(root, nodes) {
  const focused = root.contains(document.activeElement) ? document.activeElement : null;
  const key = focused?.dataset;
  root.replaceChildren(...nodes);
  if (key?.action) {
    $$('button', root).find((button) => (
      button.dataset.action === key.action && button.dataset.id === key.id && button.dataset.emoji === key.emoji
    ))?.focus({ preventScroll: true });
  }
}

let sidebarSignature, memberSignature;

function renderNavigation() {
  const selected = state.channel;
  if (selected) {
    $('#channel-title').textContent = channelLabel(selected);
    $('#channel-topic').textContent = selected.topic;
    input.placeholder = 'Write to ' + channelLabel(selected);
  }
  const sidebarKey = JSON.stringify([state.servers.map((server) => server.channels), selected?.id]);
  if (sidebarKey !== sidebarSignature) {
    sidebarSignature = sidebarKey;
    const groups = state.servers.map((server) => {
      const section = el('section', 'room-group');
      const title = el('h3', 'room-group-title', server.id === state.spaces.classes ? 'Class rooms' : 'BIC Campus');
      if (server.id === state.spaces.classes) {
        title.id = 'class-heading';
        title.tabIndex = -1;
      }
      section.append(title);
      for (const channel of server.channels) {
        const name = channelLabel(channel);
        const button = action('', 'channel', channel.id, 'channel-button' + (channel.unread ? ' unread' : ''));
        const icon = el('span', 'room-symbol', channel.id === state.spaces.global ? '◉' : channel.readOnly ? '✦' : '#');
        icon.setAttribute('aria-hidden', 'true');
        button.append(icon, el('span', 'channel-name', name));
        if (channel.unread) button.append(el('span', 'count', channel.unread));
        if (channel.id === selected?.id) button.setAttribute('aria-current', 'true');
        button.title = name;
        button.setAttribute('aria-label', name + (channel.unread ? ', ' + channel.unread + ' unread' : ''));
        section.append(button);
      }
      return section;
    });
    replaceControls($('#channel-list'), groups);
  }
  const members = state.server?.members || [];
  const memberKey = JSON.stringify(members);
  if (memberKey !== memberSignature) {
    memberSignature = memberKey;
    const items = members.map((member) => {
      const item = el('li');
      const info = el('div', 'member-info');
      info.append(el('strong', '', member.name), el('small', '', member.role === 'owner' ? 'Space steward' : 'Guest'));
      item.append(avatar(member.name), info);
      return item;
    });
    replaceControls($('#member-list'), items.length ? items : [el('li', 'muted', 'Nobody to show yet.')]);
  }
}

function renderMessages(keepBottom = state.reachedBottom) {
  const messages = [...state.rows.values()].sort((a, b) => a.seq - b.seq);
  const queued = state.saved.queued.filter((item) => item.channel === state.channel?.id);
  const children = messages.map((message) => card(message, state.user, state.server.role));
  for (const item of queued) {
    if (state.rows.has(item.id)) continue;
    children.push(card({
      id: item.id, author: state.user.name, authorId: state.user.id, text: item.text, createdAt: item.createdAt,
      replyToId: item.replyToId, replyText: item.replyText, replyAuthor: item.replyAuthor,
    }, state.user, state.server.role, { ...item, sending: state.sending.has(item.id) }));
  }
  const oldTop = stream.scrollTop;
  replaceControls($('#messages'), children);
  $('#older-button').hidden = !state.older;
  const empty = state.channel.readOnly ? 'No announcements yet.' : 'No messages here yet. Start the conversation.';
  $('#messages-status').textContent = children.length ? '' : state.loading ? 'Loading messages…' : empty;
  stream.scrollTop = keepBottom ? stream.scrollHeight : oldTop;
}

function selectedStill(navigation, user = state.user?.id) {
  return navigation === state.navigation && state.user?.id === user;
}

function updateReply() {
  const box = $('#reply-preview');
  box.hidden = !state.replying;
  $('span', box).textContent = state.replying ? 'Replying to ' + state.replying.author + ' · ' + state.replying.text.slice(0, 110) : '';
}

async function updateRead() {
  if (!state.channel || !state.rows.size || document.hidden || !state.reachedBottom || boards.has(state.pane)
    || matchMedia('(max-width: 720px)').matches && state.pane !== 'chat') return;
  const target = [...state.rows.values()].reduce((highest, row) => Math.max(highest, row.seq), 0);
  if (target <= state.lastRead) return;
  const version = state.navigation;
  await request('/channels/' + state.channel.id + '/read', 'POST', { seq: target });
  if (selectedStill(version)) {
    state.lastRead = Math.max(state.lastRead, target);
    if (state.channel.unread) {
      state.channel.unread = 0;
      renderNavigation();
    }
  }
}

function merge(messages) {
  let changed = false;
  for (const row of messages) {
    if (JSON.stringify(state.rows.get(row.id)) !== JSON.stringify(row)) changed = true;
    state.rows.set(row.id, row);
  }
  const pending = state.saved.queued.filter((item) => item.channel !== state.channel?.id || !state.rows.has(item.id));
  if (pending.length !== state.saved.queued.length) {
    state.saved.queued = pending;
    remember();
    changed = true;
  }
  return changed;
}

async function openChannel(channelId, focus = true, jump = null) {
  const server = state.servers.find((space) => space.channels.some((room) => room.id === channelId));
  const channel = server?.channels.find((room) => room.id === channelId);
  if (!channel) return;
  for (const board of boards.values()) board.close();
  state.server = server;
  const version = ++state.navigation;
  state.channel = channel;
  state.rows = new Map();
  state.cursor = null;
  state.before = null;
  state.older = false;
  state.lastRead = 0;
  state.loading = true;
  state.reachedBottom = !jump;
  state.replying = null;
  input.value = state.saved.drafts[channelId] || '';
  updateReply();
  $('#conversation').hidden = false;
  composer.hidden = Boolean(channel.readOnly);
  state.saved.channel = channelId;
  remember();
  pane('chat');
  renderNavigation();
  renderMessages();
  if (focus) $('#channel-title').focus({ preventScroll: true });
  try {
    const feed = await request('/channels/' + channelId + '/messages');
    if (!selectedStill(version)) return;
    state.loading = false;
    merge(feed.messages);
    state.cursor = feed.cursor;
    state.before = feed.messages[0]?.seq ?? null;
    state.older = feed.hasOlder;
    if (jump) {
      while (!state.rows.has(jump.id) && state.older && selectedStill(version)) await loadOlder(false);
    }
    if (!selectedStill(version)) return;
    renderMessages(!jump);
    if (jump) {
      const result = $$('[data-message]', stream).find((item) => item.dataset.message === jump.id);
      if (result) {
        result.scrollIntoView({ block: 'center' });
        result.focus({ preventScroll: true });
      } else notice('That search result is no longer available.');
    } else {
      await updateRead();
    }
  } catch (error) {
    if (!selectedStill(version)) return;
    state.loading = false;
    status($('#messages-status'), error.message, true);
    connectionError(error);
  }
}

async function loadOlder(redraw = true) {
  if (!state.channel || !state.older || !state.before) return;
  const version = state.navigation;
  const before = state.before;
  const oldHeight = stream.scrollHeight;
  const oldTop = stream.scrollTop;
  const feed = await request('/channels/' + state.channel.id + '/messages?before=' + before);
  if (!selectedStill(version)) return;
  merge(feed.messages);
  state.before = feed.messages[0]?.seq ?? before;
  state.older = feed.hasOlder;
  if (redraw) {
    renderMessages(false);
    stream.scrollTop = oldTop + stream.scrollHeight - oldHeight;
  }
}

async function readSpaces(spaces) {
  return Promise.all([request('/servers/' + spaces.campus), request('/servers/' + spaces.classes)]);
}

async function sync() {
  if (!state.user || state.syncing) return;
  state.syncing = true;
  const version = state.navigation;
  const user = state.user.id;
  try {
    const servers = await readSpaces(state.spaces);
    if (!selectedStill(version, user)) return;
    state.servers = servers;
    const server = servers.find((space) => space.id === state.server?.id);
    if (server) state.server = server;
    const channel = server?.channels.find((room) => room.id === state.channel?.id);
    if (channel) state.channel = channel;
    renderNavigation();
    const board = boards.get(state.pane);
    if (board) {
      await board.poll();
    } else if (channel && state.cursor === null && !state.loading && state.pane === 'chat') {
      await openChannel(channel.id, false);
    } else if (channel && state.cursor !== null) {
      let changed = false, more;
      do {
        const delta = await request('/channels/' + channel.id + '/messages?cursor=' + state.cursor);
        if (!selectedStill(version, user)) return;
        state.cursor = delta.cursor;
        const visible = delta.messages.filter((row) => !state.before || row.seq >= state.before || state.rows.has(row.id));
        changed = merge(visible) || changed;
        more = delta.more;
      } while (more);
      if (changed) renderMessages();
      await updateRead();
    }
    connected(true, 'Connected');
  } catch (error) {
    if (state.user?.id === user) connectionError(error);
  } finally {
    state.syncing = false;
  }
}

async function startGuest() {
  if (starting) return;
  starting = true;
  $('#startup-retry').hidden = true;
  status($('#startup-status'), 'Opening the student space…');
  try {
    const createSession = () => request('/auth/guest', 'POST', {});
    const { user, spaces } = await (!localPreview && navigator.locks
      ? navigator.locks.request('commonroom-guest', createSession) : createSession());
    const servers = await readSpaces(spaces);
    state.user = user;
    state.spaces = spaces;
    state.servers = servers;
    state.saved = loadSaved(user.id);
    for (const [name, selector, kind] of [['issues', '#thread-view', 'issue'], ['help', '#help-view', 'help']]) {
      boards.set(name, createThreads({ root: $(selector), kind, guestId: user.id, notice, onAuthExpired: reconnectGuest }));
    }
    $('#guest-name').textContent = user.name;
    $('#account-name').textContent = user.name;
    $('#account-avatar').textContent = initials(user.name);
    $('#startup').hidden = true;
    view.hidden = false;
    renderNavigation();
    connected(true, 'Connected');
    const preferred = servers.some((server) => server.channels.some((room) => room.id === state.saved.channel))
      ? state.saved.channel : spaces.global;
    await openChannel(preferred, false);
  } catch (error) {
    state.user = null;
    view.hidden = true;
    $('#startup').hidden = false;
    status($('#startup-status'), error.message, true);
    $('#startup-retry').hidden = false;
  } finally {
    starting = false;
  }
}

function reconnectGuest() {
  if (starting) return;
  state.navigation++;
  state.user = state.channel = state.server = null;
  for (const board of boards.values()) board.close();
  if (dialog.open) dialog.close();
  view.hidden = true;
  $('#startup').hidden = false;
  return startGuest();
}

async function sendQueued(id) {
  const item = state.saved.queued.find((pending) => pending.id === id);
  if (!item || state.sending.has(id)) return;
  const user = state.user.id;
  state.sending.add(id);
  if (state.channel?.id === item.channel) renderMessages(true);
  try {
    const { message } = await request('/channels/' + item.channel + '/messages', 'POST', {
      id: item.id, text: item.text, replyToId: item.replyToId,
    });
    if (state.user?.id !== user) return;
    state.saved.queued = state.saved.queued.filter((pending) => pending.id !== id);
    if (state.channel?.id === item.channel) state.rows.set(message.id, message);
    connected(true, 'Connected');
  } catch (error) {
    if (state.user?.id !== user) return;
    item.error = error.message;
    if (!error.status || error.status >= 500) connected(false, 'Message unsent. Check your connection and retry.');
  } finally {
    state.sending.delete(id);
    if (state.user?.id === user) {
      remember();
      if (state.channel?.id === item.channel) renderMessages(true);
    }
  }
}

input.addEventListener('input', () => {
  if (!state.channel) return;
  if (input.value) state.saved.drafts[state.channel.id] = input.value;
  else delete state.saved.drafts[state.channel.id];
  remember();
});

input.addEventListener('keydown', (event) => {
  if (event.key === 'Enter' && !event.shiftKey && !event.isComposing) {
    event.preventDefault();
    composer.requestSubmit();
  }
});

composer.addEventListener('submit', (event) => {
  event.preventDefault();
  if (!state.channel || state.channel.readOnly) return;
  if (!input.value.trim()) {
    notice('Write a message before sending.');
    return;
  }
  const quoted = state.replying;
  const item = {
    channel: state.channel.id, id: crypto.randomUUID(), text: input.value.trim(), createdAt: Date.now(),
    replyToId: quoted?.id ?? null, replyText: quoted?.text.slice(0, 140), replyAuthor: quoted?.author,
  };
  state.saved.queued.push(item);
  delete state.saved.drafts[state.channel.id];
  remember();
  input.value = '';
  state.replying = null;
  updateReply();
  sendQueued(item.id);
});

stream.addEventListener('scroll', () => {
  const atBottom = stream.scrollHeight - stream.scrollTop - stream.clientHeight < 48;
  const reached = atBottom && !state.reachedBottom;
  state.reachedBottom = atBottom;
  if (reached) updateRead().catch(connectionError);
});

function displayDialog(title, content) {
  dialogVersion++;
  $('#dialog-title').textContent = title;
  $('#dialog-content').replaceChildren(...content);
  status($('#dialog-status'), '');
  if (!dialog.open) dialog.showModal();
  const focus = $('#dialog-content').querySelector('input, select, textarea, button');
  focus?.focus();
  return dialogVersion;
}

function formDialog(title, controls, label, submit, { stay = false } = {}) {
  const form = el('form');
  const confirm = el('button', 'primary', label);
  confirm.type = 'submit';
  form.append(...controls, confirm);
  const version = displayDialog(title, [form]);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    confirm.disabled = true;
    status($('#dialog-status'), 'Working…');
    try {
      await submit(new FormData(form));
      if (dialogVersion !== version || !dialog.open) return;
      status($('#dialog-status'), '');
      if (!stay) dialog.close();
    } catch (error) {
      if (dialogVersion === version && dialog.open) status($('#dialog-status'), error.message, true);
      else notice(error.message);
    } finally {
      confirm.disabled = false;
    }
  });
  return form;
}

function confirmation(title, description, label, perform) {
  formDialog(title, [el('p', 'muted', description)], label, perform);
}

const searchMatches = new Map();
function searchDialog() {
  const server = state.server.id;
  const results = el('ul', 'dialog-list');
  const form = formDialog('Search messages', [field('Search this server', 'query', { max: 80 })], 'Search', async (data) => {
    const { matches } = await request('/servers/' + server + '/search?q=' + encodeURIComponent(data.get('query')));
    searchMatches.clear();
    results.replaceChildren(...(matches.length ? matches.map((match) => {
      searchMatches.set(match.id, match);
      const row = el('li');
      const button = action(match.author + ' · #' + match.channel, 'search-result', match.id, 'text-button');
      row.append(button, el('p', '', match.text.slice(0, 180)));
      return row;
    }) : [el('li', 'muted', 'No matching messages in channels you can access.')]));
  }, { stay: true });
  results.setAttribute('aria-label', 'Search results');
  form.after(results);
}

async function reaction(message, emoji) {
  const version = state.navigation;
  const active = !message.reactions?.find((item) => item.emoji === emoji)?.mine;
  const { message: result } = await request('/messages/' + message.id + '/reaction', 'PUT', { emoji, active });
  if (selectedStill(version)) {
    state.rows.set(result.id, result);
    renderMessages();
  }
}

async function rowAction(actionName, id, button) {
  const message = state.rows.get(id);
  if (actionName === 'retry-message') return sendQueued(id);
  if (actionName === 'discard-message') {
    confirmation('Discard unsent message?', 'This removes the saved retry from this browser.', 'Discard', () => {
      state.saved.queued = state.saved.queued.filter((item) => item.id !== id);
      remember();
      renderMessages();
    });
    return;
  }
  if (!message || message.deletedAt) return;
  if (actionName === 'reply') {
    state.replying = message;
    updateReply();
    input.focus();
  }
  if (actionName === 'react') {
    const choices = el('div', 'actions');
    for (const emoji of reactionEmoji) {
      const control = action(emoji, 'pick-reaction', id);
      control.dataset.emoji = emoji;
      control.setAttribute('aria-label', 'Toggle ' + emoji + ' reaction');
      choices.append(control);
    }
    displayDialog('React to message', [choices]);
  }
  if (actionName === 'pick-reaction' || actionName === 'toggle-reaction') {
    await reaction(message, button.dataset.emoji);
    if (actionName === 'pick-reaction') dialog.close();
  }
  const version = state.navigation;
  if (actionName === 'edit-message') {
    const editorUser = state.user.id;
    const editor = formDialog('Edit message', [
      field('Message', 'text', { multiline: true, max: 2000, value: state.saved.edits[id] ?? message.text }),
    ], 'Save changes', async (data) => {
      const result = await request('/messages/' + id, 'PATCH', {
        text: data.get('text'), editedAt: message.editedAt ?? null,
      });
      if (state.user?.id !== editorUser) return;
      delete state.saved.edits[id];
      remember();
      if (selectedStill(version)) {
        state.rows.set(id, result.message);
        renderMessages();
      }
      notice('Message edited.');
    });
    editor.elements.text.addEventListener('input', () => {
      if (state.user?.id !== editorUser) return;
      state.saved.edits[id] = editor.elements.text.value;
      remember();
    });
  }
  if (actionName === 'delete-message') confirmation('Remove this message?', 'The text will be removed from the conversation.', 'Remove message', async () => {
    const result = await request('/messages/' + id, 'DELETE');
    if (selectedStill(version)) {
      state.rows.set(id, result.message);
      renderMessages();
    }
    notice('Message removed.');
  });
}

async function runAction(name, id, button) {
  if (name === 'start') return startGuest();
  if (name === 'close-dialog') return dialog.close();
  if (!state.user) return;
  if (name === 'global') return openChannel(state.spaces.global);
  if (name === 'classes') {
    if (matchMedia('(max-width: 720px)').matches) pane('rooms');
    $('#class-heading')?.focus();
    return;
  }
  if (name === 'channel') return openChannel(id);
  if (boards.has(name)) {
    state.navigation++;
    $('#conversation').hidden = true;
    for (const [key, board] of boards) {
      if (key !== name) board.close();
    }
    pane(name);
    return boards.get(name).open();
  }
  if (name === 'people') {
    pane('people');
    $('#people-title').focus();
    return;
  }
  if (name === 'toggle-people') {
    const open = view.dataset.members !== 'true';
    view.dataset.members = String(open);
    $('[aria-controls="people-panel"]').setAttribute('aria-expanded', String(open));
    if (open) $('#people-title').focus();
    else $('[aria-controls="people-panel"]').focus();
    return;
  }
  if (name === 'search') return searchDialog();
  if (name === 'search-result') {
    const match = searchMatches.get(id);
    if (match) {
      dialog.close();
      await openChannel(match.channelId, true, match);
    }
    return;
  }
  if (name === 'older') {
    button.disabled = true;
    try { await loadOlder(); } finally { button.disabled = false; }
    return;
  }
  if (name === 'cancel-reply') {
    state.replying = null;
    updateReply();
    input.focus();
    return;
  }
  if (name === 'retry-connection') return sync();
  if (id) return rowAction(name, id, button);
}

document.addEventListener('click', (event) => {
  const button = event.target.closest('button[data-action]');
  if (!button) return;
  const { action: name, id } = button.dataset;
  runAction(name, id, button).catch((error) => {
    if (dialog.open) status($('#dialog-status'), error.message, true);
    else notice(error.message);
  });
});

if (localPreview) {
  document.addEventListener('commonroom-preview-temporary', () => {
    if (temporaryPreview) return;
    temporaryPreview = true;
    connected(true, 'Connected');
    notice('Browser storage is unavailable. Posts will last until you close or reload this tab.');
  });
  window.addEventListener('storage', (event) => {
    if (event.key === 'ram-for-bic-theme') updateTheme();
  });
}

await startGuest();
setInterval(() => { if (!document.hidden) sync(); }, 3000);
window.addEventListener('online', () => state.user ? sync() : startGuest());
window.addEventListener('offline', () => { if (state.user && !localPreview) connected(false, 'Offline'); });
document.addEventListener('visibilitychange', () => { if (!document.hidden) sync(); });

})();
